mkdir -p bootstrap && cd bootstrap
cat > versions.tf <<'EOF'
terraform {
  required_version = ">= 1.10.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}
EOF
cat > providers.tf <<'EOF'
provider "aws" {
  region = var.region
}
EOF
cat > variables.tf <<'EOF'
variable "region" {
  type        = string
  description = "AWS region the state bucket is created in. Must match the region in the backend block of the parent configuration."
  default     = "eu-north-1"
}

variable "state_bucket_name" {
  type        = string
  description = "Name of the S3 bucket that holds Terraform state. S3 bucket names are global, so choose a unique one. Must match the bucket in the backend block of the parent configuration."

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]$", var.state_bucket_name))
    error_message = "The bucket name must be 3 to 63 characters of lowercase letters, digits, dots, and hyphens."
  }
}

variable "noncurrent_version_retention_days" {
  type        = number
  description = "Days a superseded state version is kept before it is deleted. Older versions are the rollback history for a corrupt or truncated state."
  default     = 90
}
EOF
cat > main.tf <<'EOF'
resource "aws_s3_bucket" "state" {
  bucket = var.state_bucket_name

  # State is the only record of managed infrastructure; block accidental deletion.
  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  # Versioning must exist before noncurrent-version rules are accepted.
  depends_on = [aws_s3_bucket_versioning.state]

  rule {
    id     = "expire-noncurrent-state-versions"
    status = "Enabled"

    filter {}

    noncurrent_version_expiration {
      noncurrent_days = var.noncurrent_version_retention_days
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

data "aws_iam_policy_document" "state" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.state.arn,
      "${aws_s3_bucket.state.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}
EOF
cat > outputs.tf <<'EOF'
output "state_bucket_name" {
  description = "Name of the state bucket, for the bucket argument in the parent configuration's backend block."
  value       = aws_s3_bucket.state.id
}
EOF
cd ..
cat > backend.tf <<'EOF'
terraform {
  backend "s3" {
    # Non-secret metadata only. Credentials come from the default AWS credential chain.
    # The bucket is created by bootstrap/; keep this name equal to its state_bucket_name.
    bucket       = "reports-tfstate-example"
    key          = "reports/terraform.tfstate"
    region       = "eu-north-1"
    encrypt      = true
    use_lockfile = true # S3 native locking, Terraform >= 1.10
  }
}
EOF
cat > .gitignore <<'EOF'
.terraform/
*.tfstate
*.tfstate.*
*.tfplan
crash.log
crash.*.log
*.tfvars
*.auto.tfvars
EOF
terraform fmt -recursive -check -diff; for d in . bootstrap; do (cd $d && terraform init -backend=false -input=false >/dev/null && terraform validate); done; which tflint; checkov -d bootstrap --quiet --compact 2>&1 | tail -30

